(window.GIM_TS=window.GIM_TS||{})["Taanit.2"]={"from":48,"a":[["\u0003אלא על נפש שבעה וכרס מלאה\u0004 ולכן ראוי היה שיאכלו ותהיה דעתם מיושבת כדי שיוכלו לומר הלל בלב שלם. ושואלים: \u0003איני\u0004 \u0005[\u0006וכי \u0005כן הוא]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב פפא איקלע לבי כנישתא\u0004 \u0005[הזדמן לבית הכנסת]\u0006 של \u0003אבי גובר וגזר תענית, וירדו להם גשמים עד חצות, ואמר הלל\u0004 מיד, \u0003ואחר כך אכלו ושתו!\u0004 ומשיבים: \u0003שאני\u0004 \u0005[שונים]\u0006 \u0003בני מחוזא דשכיחי בהו\u0004 \u0005[שמצויה בהם]\u0006 \u0003שכרות,\u0004 ואם היה אומר להם ללכת לביתם לאכול ולשתות היו משתכרים, ושוב לא היו יכולים להתפלל לאחר מכן.","","\u0003בשלשה פרקים\u0004 (זמנים) \u0003בשנה כהנים נושאין את כפיהם\u0004 לברך את העם \u0003ארבע פעמים ביום; ב\u0004תפילת \u0003שחרית, במוסף, במנחה, וב\u0004תפילה נוספת של \u0003נעילת שערים\u0004 סמוך לערב. ואלה הם שלושת הפרקים: \u0003בתעניות\u0004 הציבור הגדולות, שמתענים על עצירת גשמים וכיוצא בזה, \u0003ובמעמדות\u0004 אשר יבוארו מיד, \u0003וביום הכפורים.\u0004","\u0003אלו הן מעמדות; לפי שנאמר: \"צו את בני ישראל את קרבני לחמי\u0004 לאשי ריח נחוחי תשמרו להקריב לי במועדו\u0003\"\u0004 (במדבר כח, ב), וכיון שכל ישראל צריכים להביא קרבנות ציבור, \u0003וכי היאך קרבנו של אדם קרב והוא אינו עומד על גביו?\u0004","וכיון שכל הציבור איננו יכול להיות בכל יום בירושלים, \u0003התקינו נביאים הראשונים\u0004 (שמואל ודוד) \u0003עשרים וארבעה משמרות\u0004 של כהנים, המשמשים שבוע אחד בכל מחצית שנה בערך ו\u0003על כל משמר ומשמר היה מעמד בירושלים של כהנים של לוים ושל ישראלים\u0004 שהם היו נמצאים עם הקרבת קרבן הציבור באותו זמן.","\u0003הגיע זמן\u0004 אותו \u0003המשמר לעלות, כהנים ולוים עולים לירושלים, וישראל שבאותו משמר\u0004 שנתחלקו ומשתייכים למשמר כהנים מסויים, מקצתם עולים לירושלים והשאר \u0003מתכנסין לעריהן,\u0004 ובמשך אותו שבוע שמשמש המשמר \u0003קוראין במעשה בראשית. ואנשי המעמד היו מתענין ארבעה ימים בשבוע מיום שני ועד יום חמישי. ולא היו מתענין ערב שבת — מפני כבוד השבת,\u0004 שלא יכנסו לשבת כשהם יגעים בתעניתם \u0003ולא באחד בשבת — כדי שלא יצאו ממנוחה ועונג ליגיעה ותענית\u0004 מיד, \u0003וימותו.\u0004 ומה היו קוראים בכל יום?","\u0003ביום הראשון\u0004 היו קוראים פרשת \u0003\"בראשית\"\u0004 (בראשית א, א-ה) \u0003ו\"יהי רקיע\"\u0004 (בראשית ו-ח). \u0003ב\u0004יום ה\u0003שני\u0004 היו קוראים \u0003\"יהי רקיע\" ו\"יקוו המים\"\u0004 (בראשית ט-יג). \u0003ב\u0004יום ה\u0003שלישי\u0004 היו קוראים \u0003\"יקוו המים\" ו\"יהי מארת\"\u0004 (בראשית יד-יט). \u0003ברביעי\u0004 היו קוראים \u0003\"יהי מארת\" ו\"ישרצו המים\"\u0004 (בראשית כ-כג). \u0003בחמישי \"ישרצו המים\" ו\"תוצא הארץ\"\u0004 (בראשית כד-לא). \u0003בששי ו\"תוצא הארץ\" \"ויכלו השמים\"\u0004 (בראשית ב, א-ג).","\u0003פרשה גדולה\u0004 מפרשיות אלה שיש בה שישה פסוקים או יותר \u0003קורין אותה בשנים\u0004 (שני אנשים עולים לקרוא בתורה), \u0003והקטנה\u0004 מזו — \u0003ביחיד,\u0004 שאין קוראים בתורה פחות משלושה פסוקים ואין מחלקים פרשה לפחות מכן. וקוראים בספר התורה \u0003בשחרית ובמוסף. ובמנחה נכנסין\u0004 בני המעמד לבית הכנסת \u0003וקורין\u0004 פרשה זו \u0003על פיהן\u0004 (בעל־פה, ולא מן הספר) \u0003כקורין את שמע\u0004 שאף בקריאת שמע אין צורך לקרוא מתוך ספר התורה. \u0003ערב שבת במנחה לא היו נכנסין\u0004 לבית הכנסת לשם קריאה בציבור \u0003מפני כבוד השבת.\u0004","וכלל אמרו: \u0003כל יום שיש בו\u0004 אמירת \u0003הלל\u0004 כגון חנוכה — \u0003אין מעמד\u0004 קורא \u0003בשחרית,\u0004 אם יום זה יש בו לא רק הלל אלא גם \u0003קרבן מוסף\u0004 (כגון רגלים ומועדים) — \u0003אין\u0004 מעמד קורא גם \u0003בנעילה,\u0004 יום של \u0003קרבן עצים\u0004 שיבואר עניינו להלן — \u0003אין\u0004 מעמד \u0003במנחה.\u0004 אלו \u0003דברי ר' עקיבא.\u0004","\u0003אמר לו בן עזאי: כך היה ר' יהושע שונה:\u0004 יום שיש בו \u0003קרבן מוסף — אין\u0004 מעמד \u0003במנחה,\u0004 יש בו \u0003קרבן עצים — אין\u0004 מעמד \u0003בנעילה. חזר ר' עקיבא\u0004 מדבריו, \u0003להיות שונה כבן עזאי.\u0004","ומעתה מבארים מהו \u0003זמן עצי כהנים והעם,\u0004 שהם ימי קרבן העצים שהיו ימי חג למשפחות מיוחדות, שבהם היו בני המשפחה מתנדבים קרבן עצים עבור המזבח. ימים אלה היו \u0003תשעה\u0004 בשנה: \u0003באחד בניסן\u0004 היה זה יומם של \u0003בני ארח בן יהודה, בעשרים בתמוז —\u0004 של \u0003בני דוד בן יהודה, בחמשה באב —\u0004 של \u0003בני פרעוש בן יהודה, בשבעה בו — בני יונדב בן רכב, בעשרה בו — בני סנאה בן בנימין, בחמשה עשר בו — בני זתוא בן יהודה,\u0004","\u0003ועמהם\u0004 היו חוגגים \u0003כהנים ולוים וכל מי שטעה בשבטו\u0004 ואינו יודע לבני איזה שבט הוא שייך, \u0003ו\u0004כן \u0003בני גונבי עלי ובני קוצעי קציעות\u0004 באותו יום היו. ובגמרא יבואר מפני מה נקראו בכינוי זה.","\u0003בעשרים בו — בני פחת מואב בן יהודה, בעשרים באלול — בני עדין בן יהודה, באחד בטבת שבו בני פרעוש\u0004 פעם \u0003שניה,\u0004 כי להם היו שני ימי קרבן עצים: בחמישה באב ובאחד בטבת. ומעירים: ו\u0003באחד בטבת לא היה בו מעמד\u0004 כלל, לפי \u0003שהיה בו הלל\u0004 משום שהוא בתוך חג חנוכה \u0003וקרבן מוסף\u0004 משום ראש חודש \u0003וקרבן עצים\u0004 כפי שאמרנו.","ומכאן להסברת ימי תעניות הציבור הקבועות. \u0003חמשה דברים\u0004 (אסונות) \u0003אירעו את אבותינו בשבעה עשר בתמוז, וחמשה\u0004 דברים אירעו \u0003בתשעה באב. בשבעה עשר בתמוז\u0004"],["\u0003נשתברו הלוחות\u0004 על ידי משה רבינו כשראה שעשו ישראל את העגל, \u0003ובטל התמיד\u0004 מחמת גזירת המלכות ולא הקריבוהו עוד, \u0003והובקעה העיר\u0004 במצור, \u0003ושרף\u0004 המצביא \u0003אפוסטמוס את התורה\u0004 בפומבי, \u0003והעמיד\u0004 מנשה \u0003צלם בהיכל.\u0004","\u0003בתשעה באב\u0004 אירעו חמישה דברים: בו ביום \u0003נגזר על אבותינו\u0004 במדבר \u0003שלא יכנסו לארץ\u0004 וימותו כולם במדבר, \u0003וחרב הבית\u0004 (המקדש) \u0003בראשונה\u0004 בימי נבוכדנצר \u0003ובשניה,\u0004 בבית שני, \u0003ו\u0004כן באותו יום \u0003נלכדה ביתר, ו\u0004באותו יום \u0003נחרשה העיר\u0004 ירושלים, שרצו לפרסם שלא תבנה עוד לעולם.","ולא זו בלבד שמתענים בתשעה באב עצמו, אלא \u0003משנכנס\u0004 חודש \u0003אב ממעטין בשמחה. שבת\u0004 (שבוע) \u0003שחל תשעה באב להיות בתוכה אסור מלספר ומלכבס\u0004 בה, אבל \u0003ב\u0004יום \u0003חמישי מותרין\u0004 לספר ולכבס, \u0003מפני כבוד השבת. ערב תשעה באב לא יאכל אדם שני תבשילין\u0004 באותה סעודה ו\u0003לא יאכל בשר, ולא ישתה יין. רבן שמעון בן גמליאל אומר: ישנה\u0004 וימעט ממנהגו באכילה. \u0003ר' יהודה מחייב בכפיית המטה,\u0004 להפוך את המיטות ולא לישון עליהם, כדרך שעושים באבל פרטי, \u0003ולא הודו לו חכמים.\u0004","וכדי להשלים את הדברים האמורים בחודש אב ולסיים בדבר טוב, \u0003אמר רבן שמעון בן גמליאל: לא היו ימים טובים לישראל כחמשה עשר באב וכיום הכפורים, שבהן בנות ירושלים יוצאות בכלי לבן שאולין\u0004 (שכל אחת שואלת מחברתה) ולמה בגדים שאולים — \u0003שלא לבייש את מי שאין לו\u0004 בגד לבן משלו, ולכן הכל לובשים בגדים שאולים. \u0003כל הכלים\u0004 (הבגדים) ששואלות הבנות \u0003טעונין טבילה,\u0004 שמא זו שלבשה אותם קודם היתה נידה, וטימאה את הבגד.","\u0003ובנות ירושלים יוצאות וחולות\u0004 (רוקדות) \u0003בכרמים. ומה היו אומרות: בחור, שא נא עיניך וראה, מה אתה בורר לך\u0004 לאשה, והיו מהן אומרות \u0003אל תתן עיניך בנוי\u0004 (ביופי), \u0003תן עיניך במשפחה,\u0004 שכן נאמר: \u0003\"שקר החן והבל היפי אשה יראת ה' היא תתהלל\"\u0004 (משלי לא, ל), \u0003ואומר\u0004 הכתוב באשה הכשרה: \u0003\"תנו לה מפרי ידיה ויהללוה בשערים מעשיה\"\u0004 (משלי לא, לא)","\u0003וכן הוא אומר \"צאינה וראינה בנות ציון במלך שלמה בעטרה שעטרה לו אמו ביום חתנתו וביום שמחת לבו\"\u0004 (שיר השירים ג, יא), וכתוב זה מתפרש על דרך הרמז, להסביר את יחודם של ימים אלה: \u0003\"ביום חתנתו\"\u0004 של \"המלך שלמה\" (= כינוי לקדוש ברוך הוא, שהוא מלך שהשלום שלו) — \u0003זה מתן תורה\u0004 ומתן תורה בלוחות השניים היה ביום הכיפורים, \u0003\"וביום שמחת לבו\" — זה בנין בית המקדש, שיבנה במהרה בימינו.\u0004","שנינו במשנה: \u0003בשלשה פרקים\u0004 (זמנים) \u0003בשנה כהנים נושאין את כפיהם\u0004 ארבע פעמים. ושואלים: כיצד נושאים את כפיהם ארבע פעמים בכל הימים הללו, והרי \u0003תעניות ומעמדות מי איכא\u0004 \u0005[האם יש\u0006 בהם\u0005]\u0006 תפילת \u0003מוסף?\u0004 אלא יש להסביר כך: \u0003חסורי מיחסרא והכי קתני\u0004 \u0005[חסרה\u0006 המשנה \u0005וכך\u0006 יש \u0005לשנותה]:\u0006 \u0003בשלשה פרקים\u0004 בשנה \u0003כהנים נושאין את כפיהן כל זמן\u0004 (בכל תפילה) \u0003שמתפללין, ויש מהן ארבעה פעמים ביום — שחרית ומוסף מנחה ונעילת שערים\u0004 כגון ביום הכיפורים, \u0003ואלו הן שלשה פרקים: תעניות ומעמדות ויום הכפורים.\u0004","\u0003אמר רב נחמן אמר רבה בר אבוה:\u0004 משנתנו \u0003זו דברי ר' מאיר, אבל חכמים אומרים: שחרית ומוסף — יש בהן נשיאת כפים, מנחה ונעילה — אין בהן נשיאת כפים.\u0004","ומסבירים, \u0003מאן\u0004 \u0005[מי הם]\u0006 \u0003חכמים\u0004 אלה החולקים על ר' מאיר — \u0003ר' יהודה היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003שחרית ומוסף מנחה ונעילה — כולן יש בהן נשיאת כפים,\u0004 אלו \u0003דברי ר' מאיר. ר' יהודה אומר: שחרית ומוסף — יש בהן נשיאת כפים, מנחה ונעילה — אין בהן נשיאת כפים. ר' יוסי אומר: נעילה יש בה נשיאת כפים, מנחה אין בה נשיאת כפים.\u0004 עד כאן לשון הברייתא.","ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה הם חלוקים],\u0006 מהו טעם המחלוקת? \u0003ר' מאיר סבר: כל יומא טעמא מאי לא פרשי כהני ידייהו במנחתא\u0004 \u0005[בכל יום מה טעם אין הכהנים פורשים את ידיהם במנחה]\u0006 לברך את העם — \u0003משום שכרות,\u0004 שהרי תפילת המנחה מתפללים אנשים לאחר סעודת הצהרים ופעמים שהם משתכרים ואסור לשיכור לברך, אבל \u0003האידנא ליכא\u0004 \u0005[עכשיו,\u0006 ביום תענית \u0005אין]\u0006 \u0003שכרות\u0004 ולכן יכולים לברך גם במנחה.","ואילו \u0003ר' יהודה סבר: שחרית ומוסף דכל יומא\u0004 \u0005[שבכל יום]\u0006 מימות השנה \u0003לא שכיח\u0004 \u0005[מצויה]\u0006 בהם \u0003שכרות — לא גזרו בהו רבנן\u0004 \u0005[בהם חכמים]\u0006 גם ביום התענית, ואילו \u0003מנחה ונעילה דכל יומא שכיחא\u0004 \u0005[שבכל יום מצויה]\u0006 \u0003שכרות\u0004 בשעה זו — \u0003גזרו בהו רבנן\u0004 \u0005[בהם חכמים]\u0006 גם בתענית, אף על פי שאין שכרות מצויה בה אף בשעה זו.","ואילו \u0003ר' יוסי סבר: מנחה דאיתה בכל יומא\u0004 \u0005[שישנה,\u0006 מצויה \u0005בכל יום]\u0006 בין ביום תענית בין ביום אחר \u0003גזרו בה רבנן\u0004 \u0005[חכמים]\u0006 שלא ישאו כפיהם אף במנחה בתענית, גזירה משום יום אחר, \u0003נעילה דליתה בכל יומא\u0004 \u0005[שאינה\u0006 מצויה \u0005בכל יום],\u0006 \u0003לא גזרו בה רבנן\u0004 \u0005[חכמים],\u0006 שכיון שתפילה יתירה זו היא רק בתענית — לא יבואו להחליף אותה בתפילת מנחה רגילה.","\u0003אמר רב יהודה אמר רב: הלכה כר' מאיר. ור' יוחנן אמר: נהגו העם כר' מאיר. ורבא אמר: מנהג כר' מאיר.\u0004 ומסבירים מה ההבדל בין פסקי הלכה אלה.","\u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 כי \u0003הלכה כר' מאיר —\u0004 כוונתו: \u0003דרשינן לה בפירקא\u0004 \u0005[דורשים אנו\u0006 הלכה זו \u0005בדרשה\u0006 פומבית ביום השבת\u0005]\u0006 להודיע לכול את ההלכה. \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003מנהג\u0004 כר' מאיר, כוונתו: \u0003מידרש לא דרשינן\u0004 \u0005[לדרוש\u0006 בציבור לעשות כן \u0005אין אנו דורשים]\u0006 אבל \u0003אורויי מורינן\u0004 \u0005[להורות, מורים אנו]\u0006 למי שבא לשאול, שכך עליו לעשות. \u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 רק \u0003נהגו\u0004 העם, כוונתו: \u0003אורויי לא מורינן\u0004 \u0005[אין אנו מורים]\u0006 לעשות כן, \u0003ואי עביד\u0004 \u0005[ואם עשה] —\u0006 \u0003עביד\u0004 \u0005[עשה],\u0006 \u0003ולא מהדרינן ליה\u0004 \u0005[ואין אנחנו מחזירים אותו].\u0006","\u0003ורב נחמן אמר: הלכה כר' יוסי.\u0004 ומסכמים: \u0003והלכה כר' יוסי.\u0004 ושואלים: אם כן, \u0003והאידנא מאי טעמא פרשי כהני ידייהו במנחתא דתעניתא\u0004 \u0005[ובזמן הזה מה טעם פורשים כהנים ידיהם במנחה של תענית]?\u0006 ומשיבים: \u0003כיון\u0004 ש\u0003בסמוך לשקיעת החמה קא פרשי\u0004 \u0005[פורשים\u0006 את כפיהם\u0005]\u0006 — \u0003כתפילת נעילה דמיא\u0004 \u0005[\u0006היא \u0005נחשבת]\u0006 ולא גזרו בה.","מתוך הדיון עולה כי \u0003דכולי עלמא מיהת\u0004 \u0005[לדעת הכל על כל פנים]\u0006 \u0003שכור אסור בנשיאת כפים,\u0004 שהרי נחלקו רק בפרטים לענין זה, ושואלים: \u0003מנהני מילי\u0004 \u0005[מניין דברים אלה]?\u0006 \u0003אמר ר' יהושע בן לוי משום\u0004 (משמו של) \u0003בר קפרא: למה נסמכה פרשת כהן מברך\u0004 (במדבר ו, כב-כז) \u0003לפרשת נזיר\u0004 (במדבר ו, א-כא)? \u0003לומר: מה נזיר אסור ביין, אף כהן מברך אסור ביין.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003אבוה\u0004 \u0005[אביו]\u0006 של \u0003ר' זירא ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהמקשה היה \u0003אושעיא בר זבדא:\u0004 אם אמנם משווים את הדינים, אם כן אמור אף, \u0003אי\u0004 \u0005[או]\u0006 \u0003מה נזיר אסור בחרצן\u0004 ענבים, שהרי אסור הוא בכל מה שיוצא מן הגפן ולא רק ביין — \u0003אף כהן מברך אסור בחרצן,\u0004 ובודאי לא נאסר המברך בכך! אלא \u0003אמר ר' יצחק: אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"לשרתו ולברך בשמו\"\u0004 (דברים י, ח), \u0003מה\u0004 כהן \u0003משרת\u0004 בעבודת המקדש \u0003מותר בחרצן — אף כהן מברך מותר בחרצן.\u0004"],["\u0003אי מה\u0004 (או מה) כהן \u0003משרת\u0004 בקודש \u0003בעל מום לא\u0004 ישרת, \u0003אף כהן מברך בעל מום לא\u0004 יברך! ודוחים: \u0003הא איתקש\u0004 \u0005[הרי הוקש,\u0006 הושווה\u0005]\u0006 גם \u0003לנזיר.\u0004","ושואלים: \u0003ומאי חזית דמקשת לקולא אקיש לחומרא\u0004 \u0005[ומה ראית שאתה משווה להקל, השווה להחמיר]\u0006 והשווהו לנזיר לענין איסור חרצן, ולכהן לענין מום! ומשיבים: בעיקרו של דבר ראיות אלה ל\u0003אסמכתא נינהו\u0004 \u0005[סמך\u0006 בלבד \u0005הן]\u0006 \u0003מדרבנן ולקולא\u0004 \u0005[מדברי סופרים, ו\u0006לכן משווים אותם רק \u0005להקל]\u0006 ולא להחמיר.","שנינו במשנה: \u0003אלו הן מעמדות: לפי שנאמר: \"צו את בני ישראל\".\u0004 ותוהים: \u0003מאי קאמר\u0004 \u0005[מה אמר]?\u0006 כלומר, מה מסביר הכתוב \"צו את בני ישראל\" את המעמדות? ומסבירים, \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003אלו הן מעמדות,\u0004 כאשר יבואר הלאה, \u0003ומה טעם תיקנו מעמדות — לפי שנאמר: \"צו את בני ישראל ואמרת אליהם את קרבני לחמי לאשי\u0004 ריח נחוחי תשמרו להקריב לי במועדו\u0003\"\u0004 (במדבר כח, ב),","\u0003והיאך קרבנו של אדם קרב והוא אינו עומד על גביו?\u0004 וכיון שכל ישראל אינם יכולים להיות תמיד בירושלים, לכך \u0003התקינו נביאים הראשונים\u0004 (שמואל ודוד) \u0003עשרים וארבעה משמרות. על כל משמר ומשמר היה מעמד בירושלים\u0004 שהיה קבוע בה \u0003של כהנים ושל לוים ושל ישראלים. הגיע זמן משמר לעלות, כהנים ולוים\u0004 שבאותו משמר \u0003עולין לירושלים\u0004 לעבוד במקדש.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003עשרים וארבעה משמרות בארץ ישראל, ושתים עשרה ביריחו.\u0004 ותוהים: \u0003שתים עשרה ביריחו?!\u0004 אם כן \u0003נפישן להו טובא\u0004 \u0005[מרובות הן הרבה]\u0006 שהרי נמצאו בסך הכל שלושים ושש משמרות! \u0003אלא,\u0004 יש לומר: \u0003שתים עשרה מהן ביריחו.\u0004 כיצד? \u0003הגיע זמן המשמר לעלות, חצי המשמר היה עולה מארץ ישראל\u0004 כולה \u0003לירושלים, וחצי המשמר היה עולה ליריחו, כדי שיספקו מים ומזון לאחיהם שבירושלים.\u0004","\u0003אמר רב יהודה אמר שמואל: כהנים, ולוים, וישראלים מעכבין את הקרבן,\u0004 שאם לא היו כל אלה במקדש — אין יוצאים ידי חובת קרבן הציבור. \u0003במתניתא תנא\u0004 \u0005[בברייתא שנה]\u0006 \u0003ר' שמעון בן אלעזר: כהנים, ולוים, וכלי שיר מעכבין את הקרבן.\u0004 ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עיקרון \u0005נחלקו]?\u0006 \u0003מר\u0004 \u0005[חכם זה],\u0006 שמואל, \u0003סבר, עיקר\u0004 חובת \u0003שירה\u0004 שנצטוו לשיר על הקרבן הריהי \u0003בפה,\u0004 והוא חלק מעבודת הלוויים, \u0003ומר\u0004 \u0005[וחכם זה],\u0006 ר' שמעון בן אלעזר, \u0003סבר\u0004 כי \u0003עיקר שירה בכלי,\u0004 ולכן אם אין כלי שיר הרי זה מעכב את הקרבן.","\u0003אמר רב חמא בר גוריא אמר רב: משה תיקן להם לישראל\u0004 בתחילה \u0003שמונה משמרות, ארבעה מ\u0004בניו של \u0003אלעזר וארבעה מ\u0004בניו של \u0003איתמר. בא שמואל והעמידן על שש עשרה, בא דוד והעמידן על עשרים וארבעה, שנאמר\u0004 לאחר שתוארו כל עשרים וארבעה משמרות הלויים והכהנים: \u0003\"בשנת הארבעים למלכות דויד נדרשו וימצא בהם גבורי חיל ביעזיר גלעד\"\u0004 (דברי הימים א' כו, לא).","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו: \u0003משה תיקן להם לישראל שמונה משמרות, ארבעה מאלעזר וארבעה מאיתמר,\u0004 ו\u0003בא דוד ושמואל והעמידן על עשרים וארבע, שנאמר: \"המה יסד דויד ושמואל הראה באמונתם\"\u0004 (דברי הימים א' ט, כב), הרי שאת הדבר הזה תיקנו שניהם יחד! ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003מיסודו של דוד ושמואל הרמתי\u0004 הוסיפו וחזרו והוסיפו במספר המשמרות ולבסוף \u0003העמידום על עשרים וארבע.\u0004","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003משה תיקן להם לישראל שש עשרה משמרות, שמונה מאלעזר ושמונה מאיתמר. וכשרבו בני אלעזר על בני איתמר, חלקום\u0004 את בני אלעזר \u0003והעמידום על עשרים וארבע\u0004 משמרות, \u0003שנאמר: \"וימצאו בני אלעזר רבים לראשי הגברים מן בני איתמר ויחלקום לבני אלעזר ראשים לבית אבות ששה עשר ולבני איתמר לבית אבותם שמונה\"\u0004 (דברי הימים א' כד, ד). \u0003ואומר: \"בית אב אחד אחז לאלעזר ואחז אחז לאיתמר\"\u0004 (דברי הימים א' כד, ו).","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ואומר\",\u0004 כלומר, מה צורך היה להביא ראיה נוספת לדבר? ומסבירים: \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003כי היכי דנפישי\u0004 \u0005[כפי שנתרבו]\u0006 \u0003בני אלעזר הכא נמי דנפישי\u0004 \u0005[כאן גם כן נתרבו]\u0006 \u0003בני איתמר,\u0004 ש\u0003שמונה\u0004 משמרות, \u0003מעיקרא\u0004 \u0005[מתחילה]\u0006 \u0003ארבעה הוו\u0004 \u0005[היו\u0006 בלבד\u0005]\u0006 כדברי רב חמא בר גוריא, על כן \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה שנאמר: \u0003\"בית אב אחד אחז לאלעזר ואחז אחז לאיתמר\",\u0004 שבני איתמר כפי שהיו כך נשארו (\"אחוז אחוז\"). על כל פנים מפסוק זה הרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על \u0003רב חמא בר גוריא\u0004 האומר כי משה תיקן להם שמונה בלבד!","ומשיבים: \u0003אמר לך\u0004 \u0005[יכול היה לענות לך]\u0006 \u0003רב חמא בר גוריא:\u0004 הרי מן הברייתא הקודמת ברור כי \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 כיצד היו סדרי המשמרות מתחילות, \u0003ואנא דאמרי כי האי תנא\u0004 \u0005[ואני שאמרתי כ\u0006שיטת \u0005תנא זה]\u0006 ש\u0003אמר שמונה\u0004 תיקן משה רבינו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ארבעה משמרות\u0004 כהונה בלבד \u0003עלו מן הגולה,\u0004 מבבל, ושאר עשרים משמרות נשארו שם. \u0003ואלו הן\u0004 העולים: \u0003ידעיה, חרים, פשחור, ואימר. עמדו נביאים שביניהם\u0004 שבעולי בבל,"],["\u0003וחלקום והעמידום על עשרים וארבעה\u0004 משמרות, כתבו את שמות המשמרות החדשים על הפתקים \u0003בללום ונתנום בקלפי. בא\u0004 אחד ממשפחת \u0003ידעיה ונטל חלקו,\u0004 כלומר, פתק אחד עבור המשמר שלו וחמש פתקאות נוספות, שהן \u0003חלק חבריו,\u0004 בסך הכל \u0003שש, בא חרים ונטל חלקו וחלק חבריו — שש, וכן פשחור, וכן אימר.\u0004","\u0003וכן התנו נביאים שביניהם: שאפילו יהויריב\u0004 שהוא \u0003ראש משמרת\u0004 (שנענה ראשון למשמרות) \u0003עולה\u0004 לארץ ישראל — \u0003לא ידחה ידעיה ממקומו\u0004 כראש משמר \u0003אלא ידעיה\u0004 ישאר \u0003עיקר, ויהויריב טפל לו.\u0004","שנינו במשנה: \u0003וישראל שבאותו משמר מתכנסין בעריהן וקורין במעשה בראשית.\u0004 שואלים: \u0003מנהני מילי\u0004 \u0005[מניין דברים אלה]\u0006 שקוראים פרשיות אלה דווקא? \u0003אמר ר' יעקב בר אחא אמר רב אסי: אלמלא מעמדות\u0004 (עסק הקרבנות) \u0003לא נתקיימו שמים וארץ, שנאמר: \"ויאמר ה' אלהים במה אדע כי אירשנה\"\u0004 (בראשית טו, ח)","\u0003אמר אברהם: רבונו של עולם! שמא ישראל חוטאין לפניך, אתה עושה להם כדור המבול וכדור הפלגה\u0004 ומשמידם? \u0003אמר ליה\u0004 \u0005[לו]\u0006 הקדוש ברוך הוא: \u0003לאו\u0004 \u0005[לא].\u0006 \u0003אמר לפניו: רבונו של עולם! הודיעני במה אירשנה\u0004 שאכן תתקיים הארץ ביד בני לעולם? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003\"קחה לי עגלה משלשת ועז משלשת\u0004 ואיל משולש ותור וגוזל\u0003\"\u0004 (בראשית טו, ט), כלומר, רמז לו על ענין הקרבנות, שבזכות הקרבנות יהיו ישראל ניצולים מן הפורענות.","\u0003אמר לפניו: רבונו של עולם! תינח\u0004 (נניח) \u0003בזמן שבית המקדש קיים, בזמן שאין בית המקדש קיים — מה תהא עליהם? אמר לו: כבר תקנתי להם סדר קרבנות, בזמן שקוראין בהן לפני — מעלה אני עליהם כאילו הקריבום לפני, ואני מוחל להם על כל עונותיהם.\u0004 וכיון שהקרבנות הם קיום לישראל וקיום לעולם — קוראים לכבוד הקרבנות בפרשת מעשה בראשית.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אנשי משמר היו מתפללין על קרבן אחיהם,\u0004 קרבנות התמיד שמקריבים במשמרם, \u0003שיתקבל ברצון, ואנשי מעמד\u0004 המצויים בעריהם \u0003מתכנסין לבית הכנסת, ויושבין ארבע תעניות\u0004 במשך אותו שבוע: \u0003בשני בשבת, בשלישי, ברביעי, ובחמישי. בשני\u0004 היו מתענים \u0003על יורדי הים\u0004 שינצלו מסכנות, מפני שנברא הים ביום השני. \u0003בשלישי — על הולכי מדברות,\u0004 שהרי יבשה הארץ ביום זה.","\u0003ברביעי על אסכרא\u0004 (מחלה מדבקת) \u0003שלא תיפול על התינוקות,\u0004 לפי שביום הרביעי נרמזה קללה (\"מאורות\" — מארת). \u0003בחמישי על עוברות\u0004 (נשים הרות) \u0003ומיניקות,\u0004 לפי שביום זה התחילה בריאת יצורים חיים. על \u0003עוברות\u0004 היו מתענים — \u0003שלא יפילו,\u0004 ועל ה\u0003מיניקות — שיניקו את בניהן\u0004 כראוי. \u0003ובערב שבת לא היו מתענין מפני כבוד השבת, קל וחומר בשבת עצמה\u0004 שלא היו מתענים.","ושואלים: \u0003באחד בשבת מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא\u0004 יתענו? \u0003אמר ר' יוחנן: מפני הנוצרים,\u0004 שזה יום השבתון שלהם, ויאמרו שאף ישראל מחשיבים אותו. \u0003ר' שמואל בר נחמני אמר: מפני שהוא שלישי ליצירה,\u0004 שהרי אדם נוצר ביום השישי, ויום ראשון הוא איפוא היום השלישי ליצירתו וקשה לו, כבכל יום שלישי שלאחר חולי או פציעה קשה לאדם.","\u0003ריש לקיש אמר: מפני נשמה יתירה,\u0004 ש\u0003אמר ריש לקיש: נשמה יתירה ניתנה בו באדם בערב שבת, במוצאי שבת נוטלין אותה ממנו, שנאמר: \"\u0004וביום השביעי \u0003שבת וינפש\"\u0004 (שמות לא, יז), ודורשים: \u0003כיון ששבת\u0004 וגמר שביתת השבת — \u0003וי אבדה נפש\u0004 יתירה של שבת. וביום הראשון הוא עדיין חלוש מחמת חסרונה.","שנינו במשנה: \u0003ביום הראשון\u0004 קוראים בפרשת \u0003\"בראשית\" ו\"יהי רקיע\". תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003\"בראשית\"\u0004 קוראים \u0003בשנים\u0004 בשני אנשים, \u0003\"יהי רקיע\" — באחד.\u0004 ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003\"יהי רקיע\" באחד — תלתא פסוקי הוו\u0004 \u0005[שלושה פסוקים הם]\u0006 ואין קוראים לאדם בתורה פחות משלושה פסוקים. \u0003אלא \"בראשית\" בשנים, מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 הלא \u0003חמישה פסוקי הויין\u0004 \u0005[פסוקים הם],\u0006 \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003הקורא בתורה\u0004 — \u0003אל יפחות משלשה פסוקים,\u0004 וכיצד יקראו לשנים חמישה?","בשאלה מה היו עושים נחלקו אמוראים, \u0003רב אמר: דולג\u0004 שקורא הראשון שלושה פסוקים, והשני חוזר וקורא את הפסוק האחרון שקרא קודמו. \u0003ושמואל אמר: פוסק\u0004 ומחלק את הפסוק השלישי לשנים. ומסבירים את טעמיהם: \u0003ורב\u0004 ש\u0003אמר דולג, מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר פוסק? קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003כל פסוקא\u0004 \u0005[פסוק]\u0006 ש\u0003לא פסקיה\u0004 \u0005[פסקו,\u0006 חילקו\u0005]\u0006 \u0003משה אנן לא פסקינן ליה\u0004 \u0005[אנו איננו פוסקים אותו].\u0006","\u0003ו\u0004על שיטת \u0003שמואל\u0004 ש\u0003אמר פוסק,\u0004 תוהים: \u0003ומי פסקינן\u0004 \u0005[והאם פוסקים,\u0006 מחלקים, \u0005אנו\u0006 פסוק לשנים\u0005]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' חנינא קרא\u0004 \u0005[מלמד התינוקות]:\u0006 \u0003צער גדול היה לי אצל ר' חנינא הגדול\u0004 לבקש ממנו ולהפציר בו שיתיר לפסוק פסוק ארוך לשנים \u0003ולא התיר לי לפסוק אלא לתינוקות של בית רבן, הואיל ולהתלמד עשוין\u0004 שאם הפסוק ארוך מדי לא יוכלו ללמדו כראוי. \u0003ושמואל\u0004 מה הוא אומר כנגד טענה זו — \u0003התם טעמא מאי\u0004 \u0005[שם,\u0006 בתינוקות, \u0005מה הוא הטעם]\u0006 \u0003משום דלא\u0004 \u0005[שאי]\u0006 \u0003אפשר\u0004 בדרך אחרת \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003לא\u0004 \u0005[אי]\u0006 \u0003אפשר,\u0004 שהרי אין מספיק פסוקים בפרשה.","\u0003ושמואל\u0004 ש\u0003אמר פוסק, מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר דולג,\u0004 כרב? ומסבירים: \u0003גזירה משום הנכנסין וגזרה משום היוצאין\u0004 שאם יבוא או יצא אדם באמצע הקריאה, לא ידע שקראו לכל אחד שלושה פסוקים שלמים, וילמד מכאן שאפשר לקרוא רק שנים בלבד.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו בברייתא: \u0003פרשה של ששה פסוקים — קורין אותה בשנים, ושל חמשה\u0004 — קוראים \u0003ביחיד. ואם הראשון קורא שלשה\u0004 בפרשה זו \u0003השני קורא שנים מפרשה זו ואחד מפרשה אחרת\u0004 הבאה אחריה. \u0003ויש אומרים: שלשה\u0004 מפרשה אחרת, \u0003לפי ש\u0004גם \u0003אין מתחילין בפרשה\u0004 לקרוא בה \u0003פחות משלשה פסוקין.\u0004","ושואלים: \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שאת הפסוק האמצעי \u0003דולג — לידלוג\u0004 \u0005[שידלוג\u0006 ויחזור עליו\u0005]\u0006 אף כאן, \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]\u0006 \u0003פוסק, ליפסוק\u0004 \u0005[שיפסוק],\u0006 שהרי הברייתא נוגדת את דברי שניהם! ודוחים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006"],["\u0003דאית לה רווחא\u0004 \u0005[שיש לו רווח],\u0006 שהרי יכול לקרוא בפרשה סמוכה, מה שאין כן במעמדות שחייב לקרוא בפרשות קבועות.","שנינו במשנה: \u0003פרשה גדולה קורין אותה בשנים בשחרית ובמוסף ובמנחה קורין על פיהן\u0004 כקוראים את שמע. \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003היכי קאמר\u0004 \u0005[כיצד אמר]?\u0006 כלומר, כיצד יש לפסק ולהבין הלכה זו? האם \u0003בשחרית ובמוסף קורין אותה בספר, ובמנחה קורין אותה על פה כקורין את שמע, או דלמא הכי קתני\u0004 \u0005[שמא כך שנה]:\u0006 \u0003בשחרית קורין אותה בספר, ובמוסף ובמנחה קורין אותה על פה כקורין את שמע?\u0004","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו בברייתא, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בשחרית ובמוסף נכנסין לבית הכנסת וקורין כדרך שקורין כל השנה\u0004 בספר תורה, \u0003ובמנחה יחיד קורא אותה\u0004 את פרשת היום \u0003על פה. אמר ר' יוסי: וכי יחיד יכול לקרות דברי תורה על פה בצבור? אלא כולן נכנסין וקורין אותה\u0004 ביחד \u0003על פה כקורין את שמע.\u0004 ומכל מקום למדנו מכאן שרק במנחה היו קוראים על פה.","שנינו במשנה ש\u0003כל יום שיש בו הלל — אין בו מעמד\u0004 בשחרית, ושיש בו קרבן מוסף — אין במנחה, ושיש בו קרבן עצים — אין בנעילה. ושואלים: \u0003מה הפרש בין זה לזה,\u0004 בין יום שיש בו מוסף ליום שיש בו קרבן עצים? ומשיבים: \u0003הללו,\u0004 כלומר, ימים שמקריבים קרבן מוסף, הם מ\u0003דברי תורה, והללו\u0004 זמני קרבן עצים הם מ\u0003דברי סופרים\u0004 ואינם דוחים אלא נעילה.","שנינו במשנה רשימת ימים שהם \u0003זמן עצי כהנים והעם וכו'. תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003למה הוצרכו לומר זמן עצי כהנים והעם? אמרו:\u0004 כך היה מעשה, \u0003כשעלו בני הגולה\u0004 בימי הבית השני \u0003לא מצאו עצים בלשכה\u0004 די הצורך עבור המזבח \u0003ועמדו\u0004 משפחות \u0003אלו והתנדבו משלהן\u0004 להביא את העצים למזבח.","\u0003וכך התנו נביאים שביניהם: שאפילו לשכה\u0004 המיועדת לכך במקדש \u0003מלאה עצים — יהיו אלו מתנדבים משלהם\u0004 בימים הללו, \u0003שנאמר: \"והגורלות הפלנו על קרבן העצים הכהנים הלוים והעם להביא לבית אלהינו לבית אבותינו לעתים מזמנים שנה בשנה לבער על מזבח ה' אלהינו ככתוב בתורה\"\u0004 (נחמיה י, לה), ואף שלאחר זמן שוב לא הוצרכו לנדבת היחידים, תיקנו לדורות הבאים לשמור זמנים אלה.","שנינו במשנה שחמישה עשר באב היה יום זמן קרבן העצים של משפחת זתוא בן יהודה \u0003ועמהם כהנים ולוים וכל מי\u0004 שלא ידע את שבטו ובני גונבי עלי ובני קוצעי קציעות. כדי להסביר את הכינוי הלא מובן של משפחות אלה מביאים ברייתא, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מה היו\u0004 אותן משפחות של \u0003בני גונבי עלי ובני קוצעי קציעות?\u0004","\u0003אמרו: פעם אחת גזרה המלכות גזירה על ישראל שלא יביאו עצים למערכה, ושלא יביאו בכורים לירושלים, והושיבו פרוזדאות\u0004 (משמרות) \u0003על הדרכים, כדרך שהושיב ירבעם בן נבט\u0004 כאשר רצה \u0003שלא יעלו ישראל לרגל.\u0004","\u0003מה עשו כשרין שבאותו הדור ויראי חטא? הביאו סלי בכורים וחיפום\u0004 (כיסו אותם) \u0003בקציעות\u0004 (תאנים יבשות) \u0003ונטלום, ו\u0004נשאו \u0003עלי על כתפיהן. וכיון שהגיעו אצל פרוזדאות, אמרו להם\u0004 השומרים: \u0003להיכן אתם הולכין?\u0004 היו \u0003אומרין להם: לעשות שני עגולי דבילה\u0004 שכובשים את הקציעות \u0003במכתשת שלפנינו ובעלי,\u0004 שאנחנו נושאים \u0003על כתפינו. כיון שעברו מהן\u0004 מהמשמרות — \u0003עיטרום\u0004 את הביכורים \u0003בסלים\u0004 הללו, \u0003והביאום לירושלים.\u0004","\u0003תנא\u0004 \u0005[שנה]\u0006 החכם: \u0003הן הן בני סלמאי הנתופתי.\u0004 ומסבירים עניינם בברייתא, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מה הן בני סלמאי הנתופתי? אמרו: פעם אחת גזרה המלכות גזירה על ישראל שלא יביאו עצים למערכה, והושיבו פרוזדאות על הדרכים כדרך שהושיב ירבעם בן נבט על הדרכים, שלא יעלו ישראל לרגל.\u0004","\u0003מה עשו יראי חטא שבאותו הדור? הביאו גזיריהן\u0004 (גזרי, חתיכות עצים) למערכה \u0003ועשו\u0004 מהם \u0003סולמות, והניחו על כתפיהם והלכו להם. כיון שהגיעו אצלן\u0004 אל המשמרות, \u0003אמרו להם\u0004 השומרים: \u0003להיכן אתם הולכין? אמרו להם: להביא גוזלות משובך שלפנינו ובסולמות שעל כתפינו. כיון שעברו מהן פירקום והעלום לירושלים.\u0004 ולכן קוראים להם בני סלמאי, על שם הסולמות שעשו.","\u0003ועליהם,\u0004 על משפחות אלה שעשו צדקה בישראל \u0003ועל כיוצא בהם הוא אומר: \"זכר צדיק לברכה\"\u0004 (משלי י, ז), ולכן מזכירים אותם גם לדורות הבאים, \u0003ועל ירבעם בן נבט וחבריו נאמר: \"ושם רשעים ירקב\"\u0004 (משלי י, ז).","שנינו במשנה: \u0003\"בעשרים בו בני פחת מואב בן יהודה\". תנא\u0004 \u0005[שנה]\u0006 החכם: \u0003בני פחת מואב בן יהודה — הן הן\u0004 בעצם \u0003בני דוד בן יהודה,\u0004 שנקרא על שם מואב משום שרות אמה של משפחת ישי ממואב היתה, אלו \u0003דברי ר' מאיר. ר' יוסי אומר: הן הן בני יואב בן צרויה,\u0004 שהרי צרויה אמו אף היא היתה בת ישי וממשפחת רות.","שנינו במשנה: \u0003בעשרים באלול בני עדין בן יהודה וכו'. תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בני עדין בן יהודה — הן הן בני דוד בן יהודה\u0004 שדוד נקרא בכינוי זה, אלו \u0003דברי ר' יהודה, ר' יוסי אומר: הן הן בני יואב בן צרויה.\u0004","שנינו במשנה ש\u0003באחד בטבת שבו בני פרעוש שניה. ו\u0004שואלים: \u0003מני מתניתין\u0004 \u0005[של מי\u0006 כדעת מי \u0005משנתנו]?\u0006 \u0003לא\u0004 כשיטת \u0003ר' מאיר, ולא\u0004 כשיטת \u0003ר' יהודה, ולא\u0004 כשיטת \u0003ר' יוסי.\u0004 ומסבירים: \u0003אי\u0004 \u0005[אם]\u0006 כשיטת \u0003ר' מאיר,\u0004 אם כן \u0003ליתני\u0004 שישנה לגבי עשרים באב \u0003שבו בני דוד בן יהודה שניה,\u0004 שהרי לדעתו בני פחת מואב הם בני דוד.","\u0003אי\u0004 \u0005[אם]\u0006 כשיטת \u0003ר' יהודה,\u0004 אם כן \u0003ליתני\u0004 \u0005[שישנה]\u0006 בעשרים באלול \u0003שבו בני דוד בן יהודה שניה,\u0004 שהרי לדעתו בני עדין הם בני דוד, ו\u0003אי\u0004 \u0005[אם]\u0006 כשיטת \u0003ר' יוסי,\u0004 אם כן \u0003ליתני שבו בני יואב בן צרויה שניה,\u0004 שהרי לשיטתו בני עדין הם בני יואב!","ומשיבים: \u0003לעולם\u0004 תפרש שמשנתנו כשיטת \u0003ר' יוסי\u0004 היא, אלא \u0003ותרי תנאי אליבא\u0004 \u0005[ושני תנאים\u0006 נחלקו \u0005לשיטת]\u0006 \u0003ר' יוסי,\u0004 שאחד מהם סבור שבני פחת מואב הם בני יואב, ולשיטה אחרת בני עדין בני יהודה הם בני מואב. ולפיכך לא קבעו את הדברים בודאות במשנה אלא השאירו את כינוי המשפחה בלא להכריע בדבר.","שנינו במשנה: \u0003באחד בטבת לא היה בו מעמד\u0004 כלל, משום שהיו בו מוסף והלל וקרבן עצים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מר קשישא\u0004 \u0005[הזקן]\u0006 \u0003בריה\u0004 \u0005[בנו]\u0006 של \u0003רב חסדא לרב אשי:\u0004"],["\u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003הלל דדחי דידיה\u0004 \u0005[שהוא דוחה את שלו],\u0006 כלומר, שביום שאומרים הלל נדחה המעמד של שחרית שהלל הוא חלק ממנה \u0003ומאי שנא\u0004 \u0005[ובמה שונה]\u0006 \u0003מוסף\u0004 שיום שיש בו מוסף \u0003דלא דחי דידיה\u0004 \u0005[שאיננו דוחה את\u0006 המעמד \u0005שלו,\u0006 של מוסף\u0005]\u0006 אלא דוחה מעמד של מנחה או נעילה?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי: השתא דלאו דידיה דחי\u0004 \u0005[עכשיו,\u0006 הרי \u0005את שאינו שלו,\u0006 של מנחה \u0005הוא דוחה]\u0006 — \u0003דידיה\u0004 \u0005[\u0006את \u0005שלו]\u0006 \u0003לא כל שכן\u0004 שידחה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי קאמינא לך\u0004 \u0005[כך אני אומר לך],\u0006 לא זה קשה בעיני, אלא להיפך: \u0003לא לידחי\u0004 \u0005[ידחה]\u0006 \u0003אלא דידיה\u0004 \u0005[\u0006את \u0005שלו],\u0006 כלומר, רק את המעמד שבמוסף ולא יותר!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003איכא\u0004 \u0005[יש]\u0006 שיטת \u0003ר' יוסי דקאי כוותך\u0004 \u0005[שעומדת,\u0006 שהיא \u0005כשיטתך),\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יוסי אומר: כל יום שיש בו מוסף — יש בו מעמד\u0004 ובכך חולק הוא על שיטת תנא קמא האומר שביום שיש בו מוסף אין בו מעמד בנעילה\u0003.\u0004 ונברר, \u0003מעמד דמאי\u0004 \u0005[של מה]\u0006 באיזה זמן? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שיש בו \u0003מעמד\u0004 ב\u0003שחרית, הא תנא קמא נמי הכי קאמר\u0004 \u0005[הרי התנא הראשון גם כן כך אמר]\u0006 שיש בו מעמד זה! \u0003אלא\u0004 תפרש שיש בו \u0003מעמד\u0004 אפילו ב\u0003מוסף\u0004 — הרי קשה לומר כן, וכי \u0003דידיה נמי לא דחי\u0004 \u0005[את המעמד שלו\u0006 שבשעת המוסף עצמו \u0005גם כן אינו דוחה]?!\u0006","\u0003אלא\u0004 תאמר שהוא דוחה מעמד של \u0003מנחה —\u0004 והרי מעמד זה \u0003קרבן עצים דחי\u0004 \u0005[דוחה]!\u0006 \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 כוונת הדברים שאינו דוחה מעמד של \u0003נעילה, שמע מינה\u0004 \u0005[למד מכאן]:\u0006 \u0003דידיה — דחי, דלאו דידיה — לא דחי\u0004 \u0005[את שלו הוא דוחה, את שאינו שלו,\u0006 של תפילה אחרת, \u0005אינו דוחה].\u0006 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","ושואלים: \u0003וליתני נמי\u0004 \u0005[ושישנה גם כן]:\u0006 \u0003באחד בניסן לא היה בו מעמד מפני שיש בו הלל\u0004 של ראש חודש \u0003וקרבן מוסף\u0004 של ראש חודש \u0003וקרבן עצים! אמר רבא: זאת אומרת הלילא דבריש ירחא לאו דאורייתא\u0004 \u0005[הלל ש\u0006אומרים \u0005בראש חודש לא\u0006 \u0005מן התורה\u0006 הוא\u0005]\u0006 אלא רק מנהג ישראל.","וראיה לכך — ש\u0003אמר ר' יוחנן משום ר' שמעון בן יהוצדק: שמונה עשר יום בשנה יחיד גומר בהן את הלל,\u0004 שכן הוא חובה על כל אדם בישראל, \u0003ואלו הן: שמונת ימי החג\u0004 (סוכות) \u0003ושמונת ימי חנוכה, ויום טוב הראשון של פסח, ויום טוב (ראשון) של עצרת\u0004 (שבועות). \u0003ובגולה\u0004 שנוהג גם יום טוב שני של גלויות מחמת הספק, הרי הם \u0003עשרים ואחד יום, ואלו הן: תשעת ימי החג,\u0004 בתוספת יום שני של שמיני עצרת (שמחת תורה), \u0003ושמונת ימי חנוכה ושני ימים הראשונים של פסח ושני ימים טובים של עצרת.\u0004","ובאותו ענין מסופר: \u0003רב איקלע\u0004 \u0005[הזדמן]\u0006 \u0003לבבל, חזינהו דקא קרו הלילא בריש ירחא\u0004 \u0005[ראה שהם קוראים הלל בראש חודש]\u0006 והוא לא הכיר מנהג זה, \u0003סבר לאפסוקינהו\u0004 \u0005[חשב להפסיק אותם]\u0006 משום שהם עושים שלא לצורך. \u0003כיון דחזא\u0004 \u0005[שראה]\u0006 \u0003דקא מדלגי דלוגי\u0004 \u0005[שהם מדלגים]\u0006 ואינם אומרים הכל, \u0003אמר שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003מנהג אבותיהם בידיהם\u0004 והם יודעים שהוא מנהג ואינו חובה. \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003יחיד לא יתחיל\u0004 הלל בראש חודש, \u0003ואם התחיל — גומר.\u0004","שנינו במשנה: \u0003חמשה דברים אירעו את אבותינו בשבעה עשר בתמוז,\u0004 ואחד מהם ש\u0003נשתברו\u0004 בו \u0003הלוחות.\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מניין לנו]\u0006 שביום זה נשתברו הלוחות? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בששה לחדש\u0004 סיון \u0003ניתנו עשרת הדברות לישראל, ר' יוסי אומר: בשבעה בו\u0004 היה הדבר. ומעירים: \u0003מאן דאמר\u0004 \u0005[\u0006לדעת \u0005מי שאומר]\u0006 כי \u0003בששה\u0004 בסיון \u0003ניתנו —\u0004 הרי \u0003בששה ניתנו, ובשבעה\u0004 בו \u0003עלה משה\u0004 להר סיני.","\u0003מאן דאמר\u0004 \u0005[מי שאמר]\u0006 \u0003בשבעה\u0004 ניתנו, לדעתו \u0003בשבעה ניתנו ובשבעה\u0004 עצמו \u0003עלה משה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויקרא אל משה ביום השביעי\u0004 מתוך הענן\u0003\"\u0004 (שמות כד, טז) \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויבא משה בתוך הענן ויעל אל ההר ויהי משה בהר ארבעים יום וארבעים לילה\"\u0004 (שמות כד, יח), ואם כן נחשב: \u0003עשרים וארבעה\u0004 ימים של חודש \u0003סיון\u0004 עד סוף החודש, \u0003ושיתסר\u0004 \u0005[ושישה עשר]\u0006 ימים נוספים של חודש \u0003תמוז,\u0004 אם כן \u0003מלו להו ארבעין\u0004","\u0003בשיבסר\u0004 \u0005[נתמלאו להם ארבעים\u0006 יום \u0005בשבעה עשר]\u0006 \u0003בתמוז. נחית אתא ותברינהו\u0004 \u0005[ירד\u0006 משה, \u0005בא ושבר]\u0006 את ה\u0003לוחות, וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויהי כאשר קרב אל המחנה וירא את העגל\u0004 ומחולות ויחר אף משה \u0003וישלך מידו את הלחות וישבר אתם תחת ההר\"\u0004 (שמות לב, יט). הרי שבשעה עשר בתמוז נשתברו הלוחות.","זה ששנינו במשנה, כי ביום זה \u0003בטל התמיד,\u0004 דבר זה הוא \u0003גמרא\u0004 \u0005[מסורת]. עוד\u0006","שנינו במשנה כי ביום זה \u0003הובקעה העיר.\u0004 ושואלים: וכי מאורע זה \u0003בשבעה עשר הוה\u0004 \u0005[היה]?\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"בחדש הרביעי בתשעה לחדש ויחזק הרעב בעיר\"\u0004 (ירמיהו נב, ו) \u0003וכתיב בתריה\u0004 \u0005[ונאמר אחריו]:\u0006 \u0003\"ותבקע העיר\"\u0004 (ירמיהו נב, ז), הרי שהעיר נבקעה בתשעה לחודש!","\u0003אמר רבא: לא קשיא\u0004 \u0005[אינו קשה];\u0006 \u0003כאן\u0004 במקרא, מדובר — \u0003בראשונה, כאן,\u0004 דברי המשנה \u0003— בשניה\u0004 בחורבן בית שני. \u0003דתניא: בראשונה הובקעה העיר בתשעה בתמוז, בשניה בשבעה עשר בו. מה ששנינו כי\u0004 ביום זה","\u0003שרף אפוסטמוס את התורה\u0004 — דבר זה ידוע לנו מ\u0003גמרא\u0004 \u0005[מסורת]. ומה ששנינו כי ביום זה\u0006","\u0003\"העמיד צלם בהיכל\", מנלן\u0004 \u0005[מנין לנו]\u0006 שהיה זה בשבעה עשר בתמוז? \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ומעת הוסר התמיד ולתת שקוץ שמם\"\u0004 (דניאל יב, יג), משמע שביום שבטל התמיד, באותו יום הושם השיקוץ.","אגב הדברים האלה שואלים: \u0003וחד הוה\u0004 \u0005[ו\u0006האם רק שיקוץ \u0005אחד היה]?\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"\u0004ישבית זבח ומנחה \u0003ועל כנף שקוצים משמם\"\u0004 (דניאל ט, כז), משמע ששמו לפחות שנים (\"שקוצים\" — לשון רבים)! \u0003אמר רבא: תרי הוו ונפל חד על חבריה ותבריה ליה לידיה,\u0004 \u0005[שנים היו, ונפל אחד על חבירו, ושבר לו את ידו]\u0006 וכיון שאחד נשבר, לכך מדברים רק על שיקוץ אחד \u0003ואשתכח דהוה כתיב\u0004 \u0005[ונמצא שהיה כתוב]\u0006 על הצלם:"],["\u0003אנת צבית לחרובי ביתא\u0004 \u0005[אתה רוצה להחריב את הבית] —\u0006 \u0003ידך אשלימת ליה\u0004 \u0005[ידך השלמתי לך],\u0006 כאילו רוצה צלם אחד לומר לחבירו — אתה רצית להחריב את הבית בכך שהטית את ישראל אחריך, לכך עשיתי אני בך נקמה.","מה ששנינו במשנה כי \u0003\"בתשעה באב נגזר על אבותינו שלא יכנסו לארץ\", מנלן\u0004 \u0005[מניין לנו]\u0006 שהיה זה אז — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויהי בחדש הראשון בשנה השנית באחד לחדש הוקם המשכן\"\u0004 (שמות מ, יז). \u0003ואמר מר\u0004 \u0005[החכם]:\u0006 \u0003שנה ראשונה\u0004 ליציאת מצרים \u0003עשה משה את המשכן,\u0004 בתחילתה של שנה \u0003שניה הקים משה את המשכן, ושלח מרגלים. וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויהי בשנה השנית בחדש השני בעשרים בחדש נעלה הענן מעל משכן העדת\"\u0004 (במדבר י, יא),","\u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויסעו מהר ה' דרך שלשת ימים\"\u0004 (במדבר י, לג). \u0003אמר ר' חמא בר חנינא: אותו היום סרו מאחרי ה',\u0004 שמיהרו לברוח מהר סיני וגילו שלא שמחו בשהותם שם. \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"והאספסף אשר בקרבו התאוו תאוה וישבו ויבכו גם בני ישראל\u0004 ויאמרו מי יאכילנו בשר\u0003\"\u0004 (במדבר יא, ד), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 שיאכלו את הבשר \u0003\"עד חדש ימים\u0004 עד אשר יצא מאפכם והיה לכם לזרא\u0003\"\u0004 (במדבר יא, כ) ולפי החשבון הזה, אם נוסיף לעשרים לחודש השני עוד שלושה ימים של המסע עד \"קברות התאוה\" הרי עשרים ושלושה, ונוסיף לכך עוד חודש (עשרים ותשעה ימים) שבו אכלו את הבשר במקום — \u0003דהוו להו עשרין ותרתין\u0004 \u0005[הרי הם\u0006 מגיעים ל\u0005עשרים ושנים]\u0006 \u0003בסיון\u0004 ומשם נסעו לחצרות,","\u0003וכתיב\u0004 \u0005[ונאמר]\u0006 אחר כך מעשה מרים וצרעתה: \u0003\"ותסגר מרים\u0004 מחוץ למחנה \u0003שבעת ימים\u0004 והעם לא נסע עד האסף מרים\u0003\"\u0004 (במדבר יב, טו), \u0003דהוו להו עשרין ותשעה\u0004 \u0005[הרי הם\u0006 מגיעים ל\u0005עשרים ותשעה]\u0006 \u0003בסיון,\u0004 ומשם נסעו למדבר פארן \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 מיד אחר כך: \u0003\"שלח לך אנשים\u0004 ויתורו את ארץ כנען\u0003\"\u0004 (במדבר יג, ב)","\u0003ותניא\u0004 \u0005[ושנינו\u0006 בברייתא\u0005]\u0006 חשבון זה: \u0003בעשרים ותשעה בסיון שלח משה מרגלים, וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"וישבו מתור הארץ מקץ ארבעים יום\"\u0004 (במדבר יג, כה), ולפי חשבון זה חזרו בתשעה באב. ושואלים: הלא \u0003הני\u0004 \u0005[אלה]\u0006 \u0003ארבעים יום נכי חד הוו\u0004 \u0005[חסר אחד הם],\u0006 שהרי אם תחשב יומיים שנותרו מסיון ועשרים ותשעה ימים של תמוז ושמונה של אב, הרי שעד תשעה באב יש רק שלושים ותשעה יום!","\u0003אמר אביי:\u0004 חודש \u0003תמוז דההיא שתא\u0004 \u0005[של אותה שנה]\u0006 \u0003מלויי מליוה\u0004 \u0005[מילאו אותו]\u0006 והיה בן שלושים יום, ולפי זה, עד תשעה באב היו בדיוק ארבעים יום. ורמז לדבר זה, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"קרא עלי מועד לשבר בחורי\"\u0004 (איכה א, טו), שהוסיפו עוד יום אחד של מועד — של ראש חודש, כדי שיארע הדבר בדיוק בתשעה באב.","\u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ותשא כל העדה ויתנו את קולם ויבכו העם בלילה ההוא\"\u0004 (במדבר יד, א), \u0003אמר רבה אמר ר' יוחנן: אותו היום — ערב תשעה באב היה. אמר להם הקדוש ברוך הוא: אתם בכיתם בכיה של חנם\u0004 בערב זה — \u0003ואני קובע לכם\u0004 בערב זה \u0003בכיה לדורות\u0004 על אסון אמיתי שיארע בו.","ועוד אירע בתשעה באב — \u0003חרב הבית בראשונה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ובחדש החמישי בשבעה לחדש היא שנת תשע עשרה שנה למלך נבכדנאצר מלך בבל בא נבוזראדן רב טבחים עבד מלך בבל ירושלם. וישרף את בית ה'\"\u0004 (מלכים ב' כה, ח-ט), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ובחדש החמישי בעשור לחדש היא שנת תשע עשרה שנה למלך נבוכדראצר מלך בבל בא נבוזראדן רב טבחים עמד לפני מלך בבל בירושלם.\u0004","וישרוף את בית ה'\u0003\"\u0004 (ירמיהו נב, יב-יג) \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003אי אפשר לומר\u0004 כי \u0003בשבעה\u0004 באב נשרף המקדש — \u0003שהרי כבר נאמר \"בעשור\", ואי אפשר לומר בעשור — שהרי כבר נאמר \"בשבעה\", הא כיצד\u0004 היה הדבר? \u0003בשבעה\u0004 באב \u0003נכנסו גוים להיכל, ואכלו וקלקלו\u0004 (חטאו) \u0003בו\u0004 בזנות ב\u0003שביעי\u0004 וב\u0003שמיני, ו\u0004ב","\u0003תשיעי סמוך לחשיכה הציתו בו את האור\u0004 (אש) \u0003והיה דולק והולך כל היום כולו, שנאמר: \"אוי לנו כי פנה היום כי ינטו צללי ערב\"\u0004 (ירמיהו ו, ד), שנאמר בנבואה על אותו ערב. \u0003והיינו\u0004 \u0005[וזהו]\u0006 ש\u0003אמר ר' יוחנן: אלמלי הייתי באותו הדור\u0004 של חורבן הבית \u0003לא קבעתיו\u0004 את הצום \u0003אלא בעשירי, מפני שרובו של היכל בו נשרף.\u0004 שהרי כפי שאמרנו התחילה השריפה רק בתשיעי בערב. \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 שקבעו זאת סבורים כי \u0003אתחלתא דפורענותא עדיפא\u0004 \u0005[התחלת הפורענות עדיפה]\u0006 לזכור, וכיון שהחלה השריפה בתשיעי, קבעו אותה ליום אבל וזכרון לחורבן.","\u0003ובשניה מנלן\u0004 \u0005[מניין לנו]\u0006 שחרב בתשעה באב, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מגלגלין זכות ליום זכאי\u0004 שקורים בו מאורעות של שמחה, \u0003וחובה ליום חייב,\u0004 שהוא תשעה באב שכבר אירע בו אסון כזה.","\u0003אמרו: כשחרב בית המקדש בראשונה אותו היום ערב תשעה באב היה, ומוצאי שבת היה, ומוצאי שביעית היתה,\u0004 כלומר: שנה הראשונה לשמיטה. \u0003ומשמרתה של יהויריב היתה\u0004 משמשת בו באותו שבוע \u0003והלוים היו אומרים שירה, ועומדין על דוכנם,\u0004 באותה שעה, \u0003ומה שירה היו אומרים —\u0004 את הפסוקים \u0003\"וישב עליהם את אונם וברעתם יצמיתם\"\u0004 (תהלים צד, כג), \u0003ולא הספיקו לומר\u0004 את סוף הפסוק \u0003\"יצמיתם ה' אלהינו\"\u0004 (תהלים צד, כג) \u0003עד שבאו גוים וכבשום. וכן בשניה\u0004 אירע אותו דבר בכל הפרטים הללו.","\u0003נלכדה ביתר\u0004 בתשעה באב — הרי זה \u0003גמרא\u0004 \u0005[מסורת].\u0006","\u0003נחרשה העיר\u0004 בתשעה באב — \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003כשחרב טורנוסרופוס הרשע את ההיכל, נגזרה גזרה על רבן גמליאל להריגה, בא אותו הגמון\u0004 שר רומאי אחד \u0003ועמד בבית המדרש, ואמר\u0004 ברמז: \u0003בעל החוטם מתבקש, בעל החוטם מתבקש.\u0004 שרמז שרבן גמליאל, שהיה בולט בדורו (כמו החוטם בפנים), מתבקש לשלטונות. \u0003שמע רבן גמליאל, אזל טשא מינייהו\u0004 \u0005[הלך והתחבא מהם]\u0006 מן הרומאים.","\u0003אזל לגביה בצנעא\u0004 \u0005[הלך\u0006 אותו הגמון רומי \u0005לפניו בסתר]\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אי מצילנא לך — מייתית לי לעלמא דאתי\u0004 \u0005[אם אני אציל אותך\u0006 ממוות, האם \u0005תביא אותי לחיי עולם הבא]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבן גמליאל: \u0003הן. אמר ליה\u0004 \u0005[לו]\u0006 ההגמון: \u0003אשתבע\u0004 \u0005[השבע]\u0006 \u0003לי. אשתבע ליה\u0004 \u0005[נשבע לו]\u0006 רבן גמליאל. \u0003סליק לאיגרא נפיל ומית\u0004 \u0005[עלה\u0006 ההגמון \u0005לגג נפל ומת].\u0006 \u0003וגמירי, דכי גזרי גזירתא ומית חד מינייהו מבטלי לגזרתייהו\u0004 \u0005[ולמודים\u0006 אנו במסורת \u0005שכאשר גוזרים הם גזירה ומת אחד מהם מבטלים את גזירתם]\u0006 ועל ידי כך בטלה הגזירה להרוג את רבן גמליאל. \u0003יצתה בת קול ואמרה: אותו הגמון מזומן לחיי העולם הבא.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003משחרב הבית בראשונה נתקבצו כיתות כיתות של פרחי כהונה\u0004 (הכהנים הצעירים) \u0003ומפתחות ההיכל בידן, ועלו לגג ההיכל, ואמרו לפניו: רבונו של עולם! הואיל ולא זכינו להיות גזברין נאמנים\u0004 לשמור את הבית כראוי, שהרי אנו רואים שהבית נחרב — \u0003יהיו מפתחות\u0004 הבית \u0003מסורות לך. וזרקום כלפי מעלה. ויצתה כעין פיסת יד וקיבלתן מהם. והם,\u0004 פרחי הכהונה, \u0003קפצו\u0004 מתוך צער \u0003ונפלו לתוך האור\u0004 (האש) הבוער במקדש.","\u0003ועליהן קונן ישעיהו הנביא: \"משא גיא חזיון מה לך אפוא כי עלית כלך לגגות. תשאות מלאה עיר הומיה קריה עליזה חלליך לא חללי חרב ולא מתי מלחמה\"\u0004 (ישעיהו כב א-ב), אלא העולים לגגות מתו בשריפה מעצמם. \u0003אף בהקדוש ברוך הוא נאמר \"\u0004כי יום מהומה ומבוסה ומבוכה לה'... \u0003מקרקר קר ושוע אל ההר\"\u0004 (ישעיהו כב, ה), שהוא מפרשו: שאף הקדוש ברוך הוא (\"שוע\" = אדון) משמיע קול (\"מקרקר\") על הר הבית שנחרב.","שנינו במשנה: \u0003משנכנס אב ממעטין בשמחה. אמר רב יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003רב שמואל בר שילת משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: כשם שמשנכנס אב ממעטין בשמחה — כך משנכנס אדר מרבין בשמחה\u0004"],["\u0003אמר רב פפא: הלכך\u0004 \u0005[משום כך],\u0006 \u0003בר\u0004 \u0005[בן]\u0006 \u0003ישראל דאית ליה דינא בהדי\u0004 \u0005[שיש לו דין עם]\u0006 \u0003גוי, לישתמיט מיניה\u0004 \u0005[שישתמט ממנו]\u0006 ולא יבוא לדין \u0003ב\u0004חודש \u0003אב דריע מזליה\u0004 \u0005[שרע מזלו]\u0006 של הישראל, \u0003ולימצי נפשיה\u0004 \u0005[וימציא את עצמו]\u0006 \u0003ב\u0004חודש \u0003אדר דבריא מזליה\u0004 \u0005[ש\u0006בו \u0005חזק מזלו]\u0006 ויש לו סיכוי להצליח.","כיון שהוזכר דבר בשם רב יהודה בנו של רב שמואל בר שילת משם רב, מובאים עוד כמה דברים ממסורת זו. על הכתוב \u0003\"לתת לכם אחרית ותקוה\"\u0004 (ירמיה כט, יא) \u0003אמר רב יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003רב שמואל בר שילת משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: אלו דקלים וכלי פשתן,\u0004 שהם דברים שנשמרים לאורך זמן ומביאים תועלת במשך כל זמן קיומם. ועוד על הכתוב \u0003\"ויאמר ראה ריח בני כריח שדה אשר ברכו ה'\"\u0004 (בראשית כז, כז), \u0003אמר רב יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003רב שמואל בר שילת משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: כריח שדה של תפוחים,\u0004 והוא הנקרא \"שדה אשר ברכו ה'\".","שנינו במשנה: \u0003שבת\u0004 (שבוע) \u0003שחל תשעה באב להיות בתוכה, אסורין לספר ולכבס. אמר רב נחמן: לא שנו\u0004 לאיסור \u0003אלא לכבס וללבוש\u0004 מיד, \u0003אבל לכבס ולהניח\u0004 כדי ללובשו לאחר תשעה באב — \u0003מותר. ורב ששת אמר: אפילו לכבס ולהניח אסור. אמר רב ששת: תדע\u0004 ששיטתי צודקת, \u0003דבטלי\u0004 \u0005[ש\u0006היו \u0005בטלים]\u0006 בשבוע זה \u0003קצרי דבי\u0004 \u0005[הכובסים מבית]\u0006 \u0003רב,\u0004 משמע שאסור לכבס כלל.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב המנונא\u0004 על שיטת רב נחמן, ממה ששנינו: \u0003בחמישי מותרים\u0004 לכבס, \u0003מפני כבוד השבת,\u0004 ונברר: \u0003למאי\u0004 \u0005[למה\u0006 לאיזה ענין\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003לכבס וללבוש\u0004 מיד \u0003מאי\u0004 \u0005[מה]\u0006 \u0003כבוד שבת איכא\u0004 \u0005[יש כאן]\u0006 שלובש בחמישי?","\u0003אלא\u0004 ודאי הכוונה היא \u0003להניח\u0004 לשבת, ומכאן נלמד \u0003ובחמישי הוא דשרי\u0004 \u0005[שמותר]\u0006 לכבס ולהניח לצורך השבת, \u0003אבל השבת כולה אסור!\u0004 ודוחים: \u0003לעולם\u0004 תפרש שהאיסור הוא רק \u0003לכבס וללבוש, ו\u0004מדובר כאן \u0003כשאין לו אלא חלוק אחד.\u0004 ש\u0003אמר ר' אסי אמר ר' יוחנן: מי שאין לו אלא חלוק אחד — מותר לכבסו\u0004 אפילו \u0003בחולו של מועד\u0004 שאסורה בו הכביסה, משום כבוד הבריות. \u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 ש\u0003אמר ר' בנימין אמר ר' אלעזר: לא שנו\u0004 לאסור, \u0003אלא לכבס וללבוש, אבל להניח — מותר.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו: \u0003אסור לכבס לפני תשעה באב, אפילו\u0004 אם תכלית הכביסה כדי \u0003להניח לאחר תשעה באב.\u0004 ועוד: \u0003וגיהוץ שלנו\u0004 של בני בבל, דינו \u0003ככיבוס שלהן\u0004 של בני ארץ ישראל, ואולם, כיבוס של בני בבל אינו נחשב כיבוס של ממש, ומותר. \u0003וכלי פשתן אין בהם משום גהוץ,\u0004 שאין הגיהוץ חשוב אלא בבגדי צמר. על כל פנים מוכח מכאן שאסור אפילו לכבס ולהניח, ואם כן \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 לדברי רב נחמן, ונדחו דבריו.","\u0003שלח רב יצחק בר גיורי משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יוחנן: אף על פי שאמרו כלי פשתן אין בהם משום גהוץ, אבל\u0004 אם גיהצם \u0003— אסור ללובשן בשבת\u0004 (בשבוע) \u0003שחל תשעה באב להיות בתוכה.\u0004","על ההגבלות והאיסורים בשבוע שחל בו תשעה באב, \u0003אמר רב: לא שנו\u0004 שכל זה אסור, \u0003אלא לפניו, אבל לאחריו\u0004 לאחר תשעה באב, אף באותו שבוע — \u0003מותר. ושמואל אמר: אפילו לאחריו נמי\u0004 \u0005[גם כן]\u0006 \u0003אסור,\u0004 עד סוף השבוע. \u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]:\u0006 \u0003שבת שחל תשעה באב להיות בתוכה — אסור לספר ולכבס, ובחמישי\u0004 — \u0003מותרין מפני כבוד השבת. כיצד?\u0004 אם \u0003חל\u0004 תשעה באב \u0003להיות באחד בשבת — מותר לכבס כל השבת\u0004 (השבוע) \u0003כולה,\u0004 כלומר, כל השבוע שלפני כן, שהרי אין זה שבוע שחל בו תשעה באב.","ואם חל \u0003בשני בשלישי ברביעי ובחמישי, לפניו — אסור, לאחריו — מותר.\u0004 אם \u0003חל להיות\u0004 תשעה באב \u0003בערב שבת — מותר לכבס בחמישי מפני כבוד השבת. ואם לא כבס בחמישי בשבת\u0004 מאיזה סיבה שהיא — \u0003מותר לכבס בערב שבת,\u0004 אף שהוא תשעה באב, \u0003מן המנחה ולמעלה\u0004 (והלאה). ומעירים: אף על פי כן \u0003לייט עלה\u0004 \u0005[\u0006היה \u0005מקלל על כך]\u0006 \u0003אביי,\u0004 מי שמכבס בתשעה באב אפילו לצורך השבת. \u0003ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003רב אחא בר יעקב\u0004 שהיה מקלל \u0003אהא\u0004 \u0005[על זה].\u0006","המשכה של הברייתא: \u0003חל\u0004 תשעה באב \u0003להיות בשני ובחמישי — קורין שלשה\u0004 אנשים בתורה, כדרך שקוראים בכל שבוע \u0003ומפטיר אחד\u0004 מאותם שלושה בנביא. חל \u0003בשלישי וברביעי — קורא אחד ומפטיר\u0004 אותו \u0003אחד, ר' יוסי אומר: לעולם קורין שלשה ומפטיר אחד\u0004 מהם, מפני תשעה באב. על כל פנים לענין איסור כיבוס לאחר תשעה באב מוכח שלא כשמואל, והרי זאת \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על שיטת \u0003שמואל! \u0004","\u0003אמר לך\u0004 \u0005[יכול היה לומר לך]\u0006 \u0003שמואל: תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 בענין זה. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003תשעה באב שחל להיות בשבת\u0004 עצמה, \u0003וכן ערב תשעה באב שחל להיות בשבת — אוכל ושותה\u0004 בשבת \u0003כל צרכו, ומעלה על שולחנו אפילו כסעודת שלמה בשעתו,\u0004 שאין חוששים לאבילות תשעה באב, ואוכל ושותה בשבת כפי רצונו. \u0003ואסור לספר ולכבס מראש חדש ועד התענית,\u0004 אלו \u0003דברי ר' מאיר. ר' יהודה אומר: כל החדש כולו אסור. רבן שמעון בן גמליאל אומר: אינו אסור אלא אותה שבת\u0004 (שבוע) \u0003בלבד.\u0004","\u0003ותניא אידך\u0004 \u0005[ושנינו\u0006 בברייתא \u0005אחרת]:\u0006 \u0003ונוהג אבל מראש חדש ועד התענית,\u0004 אלו \u0003דברי ר' מאיר. ר' יהודה אומר: כל החדש כולו אסור, רבן שמעון בן גמליאל אומר: אינו אסור אלא אותה שבת בלבד.\u0004 ועל כל פנים משמע מכאן שישנן שיטות (רבי יהודה ורבן שמעון בן גמליאל) האוסרות גם לאחר התענית, וכדברי שמואל.","\u0003אמר ר' יוחנן ושלשתן,\u0004 שלושת התנאים החלוקים הללו, \u0003מקרא אחד דרשו\u0004 בצורות שונות; \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והשבתי כל משושה חגה חדשה ושבתה\"\u0004 (הושע ב, יג). \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003מראש חדש ועד התענית,\u0004"],["\u0003מחגה\u0004 שמראש חודש (שהוא כיום חג) אסור. \u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 כל החודש \u0003כולו אסור —\u0004 לומד הוא זאת \u0003מ\"חדשה\", ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 \u0003כל השבת כולה אסור —\u0004 לומד הוא זאת \u0003מ\"שבתה\".\u0004","ולהלכה, \u0003אמר רבא: הלכה כרבן שמעון בן גמליאל. ואמר רבא: הלכה כר' מאיר.\u0004 ומעירים: \u0003ותרוייהו לקולא\u0004 \u0005[ו\u0006שיטות \u0005שניהם להקל\u0006 נאמרו\u0005],\u0006 \u0003וצריכא\u0004 \u0005[וצריך]\u0006 להשמיענו את שניהם. \u0003דאי אשמועינן\u0004 \u0005[שאילו היה משמיע לנו]\u0006 רק \u0003הלכה כר' מאיר הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 שהאבילות מתחילה \u0003אפילו מראש חדש,\u0004 כר' מאיר, על כן \u0003קמשמע לן\u0004 \u0005[השמיע לנו]\u0006 ש\u0003הלכה כרבן שמעון בן גמליאל,\u0004 שאין האבילות והאיסורים אלא בשבוע שחל בו תשעה באב.","\u0003ואי אשמועינן\u0004 \u0005[ואילו היה משמיע לנו]\u0006 רק \u0003הלכה כרבן שמעון בן גמליאל הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 שיש לנהוג אבילות \u0003אפילו לאחריו\u0004 עד סוף השבת אסור, על כן \u0003קמשמע לן\u0004 \u0005[השמיע לנו]\u0006 כי \u0003הלכה כר' מאיר\u0004 שעד תשעה באב ולא יותר.","שנינו במשנה: \u0003ערב תשעה באב לא יאכל אדם שני תבשילין כו'. אמר רב יהודה: לא שנו\u0004 דין זה \u0003אלא משש שעות,\u0004 כלומר: מאחר חצות היום \u0003ולמעלה\u0004 (והלאה), \u0003אבל משש שעות ולמטה,\u0004 כלומר: קודם לכן — \u0003מותר. ואמר רב יהודה: לא שנו\u0004 כן, \u0003אלא בסעודה המפסיק בה\u0004 שלאחריה מתחיל לצום, \u0003אבל בסעודה שאינו מפסיק בה — מותר.\u0004","ומעירים: \u0003ותרוייהו לקולא\u0004 \u0005[ושניהם\u0006 נאמרו \u0005להקל],\u0006 שיש לצרף את שני הדברים הללו להקל. \u0003וצריכא\u0004 \u0005[וצריך]\u0006 שייאמרו שניהם. \u0003דאי אשמעינן\u0004 \u0005[שאילו היה משמיע לנו]\u0006 רק שהאיסור הוא \u0003בסעודה המפסיק בה, הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003אפילו משש שעות ולמטה,\u0004 שאם מפסיק בסעודה קודם חצי היום אסור לו לאכול בה שני תבשילים — על כן \u0003קמשמע לן\u0004 \u0005[השמיע לנו]\u0006 כי דין זה אינו אלא \u0003משש שעות ולמעלה\u0004 בלבד, \u0003ואי אשמעינן\u0004 \u0005[ואילו היה משמיע לנו]\u0006 כי האיסור הוא \u0003משש שעות ולמעלה, הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 שזהו \u0003אפילו בסעודה שאינו מפסיק בה,\u0004 על כן \u0003קמשמע לן\u0004 \u0005[השמיע לנו]\u0006 שזהו דווקא \u0003בסעודה המפסיק בה.\u0004","ומעירים: \u0003תניא כלישנא קמא תניא כלישנא בתרא\u0004 \u0005[שנויה\u0006 ברייתא \u0005כלשון ראשונה, שנויה כלשון שניה]\u0006 \u0003תניא כלישנא בתרא\u0004 \u0005[שנויה\u0006 ברייתא \u0005כלשון אחרונה]:\u0006 \u0003הסועד ערב תשעה באב, אם עתיד לסעוד סעודה אחרת\u0004 אחריה — \u0003מותר לאכול\u0004 בסעודה הראשונה \u0003בשר ולשתות יין, ואם לאו\u0004 שאינו אוכל עוד סעודה אחרת — \u0003אסור לאכול בשר ולשתות יין.\u0004","\u0003תניא כלישנא קמא\u0004 \u0005[שנויה\u0006 ברייתא גם \u0005כלשון ראשונה]:\u0006 \u0003ערב תשעה באב לא יאכל אדם שני תבשילין, לא יאכל בשר ולא ישתה יין, רבן שמעון בן גמליאל אומר ישנה\u0004 ממנהג אכילתו. \u0003אמר ר' יהודה: כיצד משנה? אם היה רגיל לאכול שני תבשילין\u0004 בסעודתו — \u0003יאכל מין אחד, ואם היה רגיל לסעוד\u0004 סעודה גדולה \u0003בעשרה בני אדם — סועד בחמשה, היה רגיל לשתות עשרה כוסות — שותה חמשה כוסות. במה דברים אמורים — משש שעות ולמעלה, אבל משש שעות ולמטה — מותר\u0004 הכל.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003ערב תשעה באב לא יאכל אדם שני תבשילין, לא יאכל בשר ולא ישתה יין.\u0004 אלו \u0003דברי ר' מאיר, וחכמים אומרים: ישנה\u0004 ממה שרגיל לאכול. \u0003וממעט בבשר וביין. כיצד ממעט? אם היה רגיל לאכול\u0004 בסעודתו \u0003ליטרא בשר — יאכל חצי ליטרא, היה רגיל לשתות לוג יין — ישתה חצי לוג יין, ואם אינו רגיל\u0004 בהם \u0003כל עיקר — אסור. רבן שמעון בן גמליאל אומר: אם היה רגיל לאכול צנון או מליח אחר סעודתו — הרשות בידו\u0004 לאוכלם גם בערב תשעה באב, ואין אנחנו אומרים שזה נחשב כמזון נוסף.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003כל שהוא משום תשעה באב,\u0004 כלומר, אם אוכל סעודה זו מפני צום תשעה באב — \u0003אסור לאכול\u0004 בה \u0003בשר ואסור לשתות\u0004 בה \u0003יין ואסור לרחוץ. כל שאינו משום תשעה באב — מותר לאכול בשר ולשתות יין ואסור לרחוץ. ר' ישמעאל בר' יוסי אומר משום\u0004 (משם) \u0003אביו: כל שעה שמותר לאכול בשר — מותר לרחוץ.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כל מצות הנוהגות באבל\u0004 פרטי — \u0003נוהגות בתשעה באב;\u0004 יום זה \u0003אסור באכילה ובשתיה, ובסיכה\u0004 בשמן, \u0003ובנעילת הסנדל, ובתשמיש המטה. ואסור לקרות בתורה בנביאים ובכתובים, ולשנות במשנה בתלמוד ובמדרש ובהלכות ובאגדות.\u0004","\u0003אבל קורא הוא במקום שאינו רגיל לקרות,\u0004 שכיון שאינו רגיל הוא מתקשה ואינו נהנה מן הדבר כל כך, \u0003ושונה במקום שאינו רגיל לשנות, וקורא בקינות\u0004 בספר איכה ו\u0003ב\u0004ספר \u0003איוב, ובדברים הרעים\u0004 נבואות פורענות \u0003שב\u0004ספר \u0003ירמיהו. ותינוקות של בית רבן בטלין\u0004 באותו יום מלימודם, \u0003משום שנאמר: \"פקודי ה' ישרים משמחי לב\"\u0004 (תהלים יט, ט).","\u0003ר' יהודה אומר: אף אינו קורא במקום שאינו רגיל לקרות, ואינו שונה במקום שאינו רגיל לשנות. אבל קורא הוא באיוב ובקינות ובדברים הרעים שבירמיהו. ותינוקות של בית רבן בטלים בו, משום שנאמר: \"פקודי ה' ישרים משמחי לב\".\u0004","שנינו במשנה: \u0003לא יאכל בשר ולא ישתה יין. תנא\u0004 \u0005[שנה\u0006 החכם \u0005בתוספתא]:\u0006 \u0003אבל אוכל הוא בשר מליח\u0004 (מלוח מאוד) \u0003ושותה יין מגתו\u0004 שעדיין לא תסס כל צרכו. ומבררים: \u0003בשר מליח\u0004 זה \u0003עד כמה\u0004 ימים יהיה במלח ויהיה אסור? \u0003אמר רב חיננא בר כהנא משמיה\u0004 \u0005[משמו]\u0006 של \u0003שמואל: כל זמן שהוא כשלמים\u0004 במשך הימים שמותר לאכול שלמים, כלומר, שני ימים ולילה אחד, אבל אם הוא מלוח יותר מזמן זה — מותר לאוכלו.","\u0003ויין מגתו\u0004 שאמרנו \u0003עד כמה\u0004 זמן נחשב הוא ככזה? \u0003כל זמן שהוא תוסס.\u0004 וכיוצא בזה \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003יין תוסס אין בו משום גילוי,\u0004 שגם אם עמד בכלי בלתי מכוסה, אין חוששים שמא שתה ממנו נחש, \u0003וכמה תסיסתו\u0004 של יין — \u0003שלשה ימים\u0004 משעה שדרכו את הענבים.","\u0003אמר רב יהודה אמר רב: כך היה מנהגו של ר' יהודה בר' אילעאי: ערב תשעה באב\u0004 סמוך ללילה היו \u0003מביאין לו פת חרבה במלח, ויושב\u0004 היה"],["\u0003בין תנור לכיריים\u0004 שהוא מקום הפחות מכובד שבבית, \u0003ואוכל\u0004 את הפת \u0003ושותה עליה קיתון\u0004 (כוס גדולה) \u0003של מים ודומה\u0004 בכל מנהגו \u0003כמי שמתו מוטל לפניו.\u0004","\u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה\u0005]:\u0006 \u0003מקום שנהגו לעשות מלאכה בתשעה באב — עושין, מקום שנהגו שלא לעשות — אין עושין, ובכל מקום\u0004 (גם במקום שנהגו לעשות מלאכה), \u0003תלמידי חכמים בטלים\u0004 ממלאכה. \u0003רבן שמעון בן גמליאל אומר: לעולם יעשה כל אדם עצמו כתלמיד חכם\u0004 לענין זה. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003רבן שמעון בן גמליאל אומר: לעולם יעשה\u0004 כל \u0003אדם עצמו\u0004 לענין זה \u0003כתלמיד חכם, כדי שיתענה,\u0004 שאם איננו עוסק במלאכה העינוי גדול יותר.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת],\u0006 \u0003רבן שמעון בן גמליאל אומר: כל האוכל ושותה בתשעה באב,\u0004 אף שהאיסור אינו אלא מדברי נביאים וסופרים — \u0003כאילו אוכל ושותה ביום הכיפורים. ר' עקיבא אומר: כל העושה מלאכה בתשעה באב — אינו רואה סימן ברכה לעולם\u0004 במלאכה זאת.","\u0003וחכמים אומרים: כל העושה מלאכה בתשעה באב ואינו מתאבל על ירושלים — אינו רואה\u0004 לעתיד \u0003בשמחתה, שנאמר \"שמחו את ירושלים וגילו בה כל אהביה שישו אתה משוש כל המתאבלים עליה\"\u0004 (ישעיהו סו, י) \u0003מכאן אמרו: כל המתאבל על ירושלים — זוכה ורואה בשמחתה, ושאינו מתאבל על ירושלים — אינו רואה בשמחתה. תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003כל האוכל בשר ושותה יין בתשעה באב,\u0004 כלומר, בסעודה המפסקת שלפניו — \u0003עליו הכתוב אומר \"ותהי עונותם על עצמתם\u0004 כי חיתית גבורים בארץ חיים\u0003\"\u0004 (יחזקאל לב, כז).","שנינו במשנה: \u0003ר' יהודה מחייב בכפיית המטה ולא הודו לו חכמים. תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 \u0003אמרו לו\u0004 חכמים \u0003לר' יהודה: לדבריך,\u0004 נשים \u0003עוברות\u0004 (הרות) \u0003ומיניקות מה תהא עליהן,\u0004 שהרי אין הן יכולות לישון על מיטה כפויה? \u0003אמר להם: אף אני לא אמרתי אלא ב\u0004מי שהוא \u0003יכול.\u0004","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003מודה ר' יהודה לחכמים בשאינו יכול\u0004 שאינו כופה מיטתו, \u0003ומודים חכמים לר' יהודה ביכול,\u0004 שראוי שיכפה מטתו. ושואלים: אם כן שהודו זה לזה, \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם\u0006 למעשה\u0005]?\u0006 ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה\u0005]\u0006 ביחס \u0003לשאר מטות.\u0004","\u0003כדתניא\u0004 \u0005[\u0006ו\u0005כפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003כשאמרו\u0004 שאבל חייב \u0003לכפות\u0004 את \u0003המטה, לא\u0004 את \u0003מטתו בלבד הוא כופה, אלא\u0004 את \u0003כל המטות כולן הוא כופה.\u0004 שלדעת ר' יהודה צריך לכפות בתשעה באב את כל המיטות שבבית. \u0003אמר רבא: הלכתא\u0004 \u0005[הלכה]\u0006 \u0003כ\u0004שיטת ה\u0003תנא דידן\u0004 \u0005[שלנו]\u0006 במשנתנו, \u0003ולא הודו לו חכמים כל עיקר;\u0004 שאפילו ביכול לא הודו לו, ולהלכה — אין כל חיוב בכפיית המיטה.","שנינו במשנה: \u0003אמר רבן שמעון בן גמליאל לא היו ימים טובים לישראל כחמשה עשר באב וכיום הכפורים.\u0004 ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003יום הכפורים\u0004 שהוא יום שמחה — \u0003משום דאית ביה\u0004 \u0005[שיש בו]\u0006 \u0003סליחה ומחילה,\u0004 ועוד שהוא \u0003יום שנתנו בו לוחות האחרונות\u0004 לישראל.","\u0003אלא חמשה עשר באב מאי היא\u0004 \u0005[מה הוא],\u0006 מה השמחה שביום זה? \u0003אמר רב יהודה אמר שמואל:\u0004 זהו \u0003יום שהותרו שבטים לבוא זה בזה.\u0004 שמיום זה והלאה בשנה מסויימת התירו לשבטי ישראל שוב להתחתן אלה באלה כרצונם, ולא הקפידו שתהיינה בנות יורשות נחלה נישאות רק לבני שבטן, כפי שנאמר לבנות צלפחד בשעתו.","ומסבירים: \u0003מאי דרוש\u0004 \u0005[מה,\u0006 איך \u0005דרשו]\u0006 את הכתוב כדי לבטל מה שגזר משה רבינו בהוראת הקדוש ברוך הוא? שנאמר: \u0003\"זה הדבר אשר צוה ה' לבנות צלפחד\u0004 לאמור לטוב בעיניהם תהיינה לנשים אך למשפחת מטה אביהם תהיינה לנשים\u0003\"\u0004 (במדבר לו, ו), ולמדו ש\u0003דבר זה לא יהא נוהג אלא בדור זה\u0004 של חלוקת הארץ לנחלות בראשונה, אבל לאחר מכן אין אנחנו חוששים עוד, ויכולות המשפחות להתחתן זו בזו. וביום שהותרו השבטים להתחתן והוסרה מחיצה זו בין שבטי ישראל, קבעו יום שמחה לדורות.","\u0003אמר רב יוסף אמר רב נחמן:\u0004 חמישה עשר באב הוא \u0003יום שהותר שבט בנימין לבוא בקהל,\u0004 שמצאו לו דרך להתיר השבועה שאסרה על שבט זה לבוא בקהל, \u0003שנאמר: \"ואיש ישראל נשבע במצפה לאמר איש ממנו לא יתן בתו לבנימן לאשה\"\u0004 (שופטים כא, א), ושואלים: \u0003מאי דרוש\u0004 \u0005[מה,\u0006 איך \u0005דרשו]\u0006 את הכתוב, ובשל כך התירו שבועה זו? \u0003אמר רב:\u0004 דקדקו בלשון \u0003\"ממנו\" ולא מבנינו,\u0004 לומר שהשבועה חלה רק עלינו, על בני דור זה, אבל לא על בני דור אחר. ואותו יום שהותר הדבר, חמישה עשר באב היה.","\u0003אמר רבה בר בר חנה אמר ר' יוחנן:\u0004 חמישה עשר באב הוא יום חג, מפני שהוא \u0003יום שכלו בו מתי מדבר,\u0004 שלא מתו עוד ישראל במדבר, שכבר כלה כל דור יוצאי מצרים. ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003עד שלא כלו מתי מדבר לא היה דבור\u0004 של ה' \u0003עם משה, שנאמר: \"ויהי כאשר תמו כל אנשי המלחמה למות\u0004 מקרב העם. \u0003וידבר ה' אלי\u0004 לאמור\u0003\"\u0004 (דברים ב, טז-יז) — \u0003אלי\u0004 היה אז \u0003הדבור,\u0004 ולא קודם לכן. וכשידעו שבטלה גזירה זו — קבעו יום זה ליום שמחה.","\u0003עולא אמר:\u0004 חמישה עשר באב הוא \u0003יום שביטל\u0004 המלך \u0003הושע בן אלה פרוסדיות\u0004 (משמרות) \u0003שהושיב ירבעם בן נבט על הדרכים\u0004 כדי \u0003שלא יעלו ישראל לרגל, ואמר\u0004 הושע בן אלה:"],["\u0003לאיזה שירצו יעלו,\u0004 שאם ירצו — יעלו לירושלים, ירצו — ילכו לבית אל או לדן.","\u0003רב מתנה אמר:\u0004 יום זה היתה בו ישועה נוספת, כי הוא \u0003יום שנתנו\u0004 בו \u0003הרוגי ביתר לקבורה,\u0004 שהתירו השלטונות הרומיים לקבור אותם, לאחר זמן רב (ראה גיטין נז, א). \u0003ואמר רב מתנה: אותו יום שנתנו\u0004 בו \u0003הרוגי ביתר לקבורה, תקנו ביבנה\u0004 ברכת \u0003\"הטוב והמטיב\", \"הטוב\" —\u0004 על \u0003שלא הסריחו, \"והמטיב\" — על\u0004 \u0003שנתנו לקבורה. רבה ורב יוסף דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 חמישה עשר באב הוא \u0003יום שפסקו מלכרות עצים למערכה\u0004 שעורכים על המזבח, והיו משתמשים בעצים ישנים. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אליעזר הגדול אומר: מחמשה עשר באב ואילך תשש כוחה של חמה, ו\u0004לכן \u0003לא היו כורתין\u0004 מתאריך זה והלאה \u0003עצים למערכה, לפי שאינן יבשין\u0004 כל צרכם ועץ שאינו יבש כל צרכו לעיתים יש בו תולעים ופסול למערכה (מדות פ\"ב מ\"ה).","","\u0003אמר רב מנשיא: וקרו ליה\u0004 \u0005[וקוראים לו]\u0006 ליום זה, \u0003יום תבר\u0004 \u0005[שבירת]\u0006 ה\u0003מגל,\u0004 ששוב אין חוטבים עצים בגרזן וכאילו לכבוד העצים עושים חגיגה זו, משום הפסקת כריתת העצים. ומעירים: \u0003מכאן ואילך,\u0004 מיום זה והלאה, מי ש\u0003מוסיף\u0004 בלימוד התורה בלילות, שמתחילים להאריך מיום זה והלאה — \u0003יוסיף\u0004 חיים, \u0003ודלא\u0004 \u0005[ו\u0006מי \u0005שלא]\u0006 \u0003מוסיף\u0004 — \u0003יאסף.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003יאסף? תני\u0004 \u0005[שנה]\u0006 \u0003רב יוסף: תקבריה אימיה\u0004 \u0005[תקברנו אמו].\u0006 כלומר, ימות בלא זמנו.","שנינו במשנה: \u0003שבהן בנות ירושלים\u0004 יוצאות במחולות בכרמים. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בפירוט: \u0003בת מלך שואלת\u0004 בגדי לבן \u0003מבת כהן גדול, בת כהן גדול\u0004 שואלת \u0003מבת סגן\u0004 שהוא בדרגה נמוכה יותר, \u0003ובת סגן מבת\u0004 כהן \u0003משוח מלחמה,\u0004 שהוא הכהן הקורא את דברי התורה לאנשי הצבא היוצאים למלחמה, \u0003ובת משוח מלחמה\u0004 שואלת \u0003מבת כהן הדיוט, וכל ישראל שואלין זה מזה.\u0004 וכל כך למה? \u0003כדי שלא יתבייש את מי שאין לו\u0004 בגדים, ולכך תיקנו שיהיו כולם שואלים בגדים זה מזה.","שנינו במשנה: \u0003כל הכלים\u0004 (הבגדים) השאולים הללו \u0003טעונין טבילה,\u0004 שמא לבשה אותן אשה נידה. \u0003אמר ר' אלעזר: אפילו\u0004 היו \u0003מקופלין ומונחין בקופסא,\u0004 שלא נגעו בהם במשך כל הזמן, מכל מקום גזרו שיטבילום.","עוד שנינו במשנה: \u0003בנות ישראל יוצאות וחולות בכרמים. תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003מי שאין לו אשה, נפנה לשם\u0004 לבחור לו שם אשה.","עוד שנינו במשנה: \u0003מיוחסות שבהן היו אומרות: בחור\u0004 שא נא עיניך וכו'. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא בפירוט: \u0003יפיפיות שבהן מה היו אומרות: תנו עיניכם ליופי, שאין האשה אלא ליופי. מיוחסות שבהן מה היו אומרות: תנו עיניכם למשפחה, לפי שאין האשה אלא לבנים\u0004 ויהיו הבנים מיוחסים ונוטים לדרך הוריהם. \u0003מכוערות שבהם מה היו אומרות: קחו מקחכם לשום\u0004 (לשם) \u0003שמים, ובלבד שתעטרונו בזהובים\u0004 אחר הנישואים, ואז נתייפה.","ואגב ענין זה של מחולות מסיימים את המסכת בענין דומה, \u0003אמר עולא ביראה\u0004 (מן העיר בירי), \u0003אמר ר' אלעזר: עתיד הקדוש ברוך הוא לעשות מחול לצדיקים, והוא יושב ביניהם בגן עדן, וכל אחד ואחד\u0004 מן הצדיקים \u0003מראה\u0004 עליו \u0003באצבעו, שנאמר: \"ואמר ביום ההוא הנה אלהינו זה קוינו לו ויושיענו זה ה' קוינו לו נגילה ונשמחה בישועתו\"\u0004 (ישעיהו כה, ט), שתהא התגלות ה' וכל אחד יוכל לומר \"זה אלהינו\" כמראה באצבע.",""]]};
